import{_ as i}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as a,d as n,o as t}from"./app-DKtpHb63.js";const r={};function s(o,e){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="alzheimers-disease-and-machine-learning" tabindex="-1"><a class="header-anchor" href="#alzheimers-disease-and-machine-learning"><span>Alzheimers Disease and Machine Learning</span></a></h1><h2 id="predicting-mild-cognitive-impairment-progression-to-alzheimer-s-disease-based-on-machine-learning-analysis-of-cortical-morphological-features" tabindex="-1"><a class="header-anchor" href="#predicting-mild-cognitive-impairment-progression-to-alzheimer-s-disease-based-on-machine-learning-analysis-of-cortical-morphological-features"><span>Predicting mild cognitive impairment progression to Alzheimer&#39;s disease based on machine learning analysis of cortical morphological features.</span></a></h2><p>PURPOSE:<br> To establish a model for predicting mild cognitive impairment (MCI) progression to Alzheimer&#39;s disease (AD) using morphological features extracted from a joint analysis of voxel-based morphometry (VBM) and surface-based morphometry (SBM).</p><p>METHODS:<br> We analyzed data from 121 MCI patients from the Alzheimer&#39;s Disease Neuroimaging Initiative, 32 of whom progressed to AD during a 4-year follow-up period and were classified as the progression group, while the remaining 89 were classified as the non-progression group.<br> Patients were divided into a training set (n = 84) and a testing set (n = 37).<br> Morphological features measured by VBM and SBM were extracted from the cortex of the training set and dimensionally reduced to construct morphological biomarkers using machine learning methods, which were combined with clinical data to build a multimodal combinatorial model.<br> The model&#39;s performance was evaluated using receiver operating characteristic curves on the testing set.</p><p>RESULTS:<br> The Alzheimer&#39;s Disease Assessment Scale (ADAS) score, apolipoprotein E (APOE4), and morphological biomarkers were independent predictors of MCI progression to AD.<br> The combinatorial model based on the independent predictors had an area under the curve (AUC) of 0.866 in the training set and 0.828 in the testing set, with sensitivities of 0.773 and 0.900 and specificities of 0.903 and 0.747, respectively.<br> The number of MCI patients classified as high-risk for progression to AD was significantly different from those classified as low-risk in the training set, testing set, and entire dataset, according to the combinatorial model (P &lt; 0.05).</p><p>CONCLUSION:<br> The combinatorial model based on cortical morphological features can identify high-risk MCI patients likely to progress to AD, potentially providing an effective tool for clinical screening.</p><p>(10.1007/s40520-023-02456-1)</p><h2 id="predicting-alzheimer-s-disease-with-interpretable-machine-learning" tabindex="-1"><a class="header-anchor" href="#predicting-alzheimer-s-disease-with-interpretable-machine-learning"><span>Predicting Alzheimer&#39;s Disease with Interpretable Machine Learning.</span></a></h2><p>INTRODUCTION:<br> This study aimed to develop novel machine learning models for predicting Alzheimer&#39;s disease (AD) and identify key factors for targeted prevention.</p><p>METHODS:<br> We included 1219, 863, and 482 participants aged 60+ years with only sociodemographic, both sociodemographic and self-reported health, both the former two and blood biomarkers information from Alzheimer&#39;s Disease Neuroimaging Initiative (ADNI) database.<br> Machine learning models were constructed for predicting the risk of AD for the above three populations.<br> Model performance was evaluated by discrimination, calibration, and clinical usefulness.<br> Shapley additive explanations (SHAP) was applied to identify key predictors of optimal models.</p><p>RESULTS:<br> The mean age was 73.49, 74.52, and 74.29 years for the three populations, respectively.<br> Models with sociodemographic information and models with both sociodemographic and self-reported health information showed modest performance.<br> For models with sociodemographic and self-reported health, and blood biomarker information, their overall performance improved substantially, specifically, LR performed best, with an AUC value of 0.818.<br> Blood biomarkers of ptau protein and plasma neurofilament light, age, blood tau protein and education level were top five significant predictors.<br> In addition, taurine, inosine, xanthine, marital status, and L.<br> Glutamine also showed importance to AD prediction.</p><p>CONCLUSION:<br> Interpretable machine learning showed promise in screening high-risk AD individual, and could further identify key predictors for targeted prevention.</p><p>(10.1159/000531819)</p><h2 id="a-unique-color-coded-visualization-system-with-multimodal-information-fusion-and-deep-learning-in-a-longitudinal-study-of-alzheimer-s-disease" tabindex="-1"><a class="header-anchor" href="#a-unique-color-coded-visualization-system-with-multimodal-information-fusion-and-deep-learning-in-a-longitudinal-study-of-alzheimer-s-disease"><span>A unique color-coded visualization system with multimodal information fusion and deep learning in a longitudinal study of Alzheimer&#39;s disease.</span></a></h2><p>PURPOSE:<br> Automated diagnosis and prognosis of Alzheimer&#39;s Disease remain a challenging problem that machine learning (ML) techniques have attempted to resolve in the last decade.<br> This study introduces a first-of-its-kind color-coded visualization mechanism driven by an integrated ML model to predict disease trajectory in a 2-year longitudinal study.<br> The main aim of this study is to help capture visually in 2D and 3D renderings the diagnosis and prognosis of AD, therefore augmenting our understanding of the processes of multiclass classification and regression analysis.</p><p>METHOD:<br> The proposed method, Machine Learning for Visualizing AD (ML4VisAD), is designed to predict disease progression through a visual output.<br> This newly developed model takes baseline measurements as input to generate a color-coded visual image that reflects disease progression at different time points.<br> The architecture of the network relies on convolutional neural networks.<br> With 1123 subjects selected from the ADNI QT-PAD dataset, we use a 10-fold cross-validation process to evaluate the method.<br> Multimodal inputs# include neuroimaging data (MRI, PET), neuropsychological test scores (excluding MMSE, CDR-SB, and ADAS to avoid bias), cerebrospinal fluid (CSF) biomarkers with measures of amyloid beta (ABETA), phosphorylated tau protein (PTAU), total tau protein (TAU), and risk factors that include age, gender, years of education, and ApoE4 gene.</p><p>FINDINGS/RESULTS:<br> Based on subjective scores reached by three raters, the results showed an accuracy of 0.82 ± 0.03 for a 3-way classification and 0.68 ± 0.05 for a 5-way classification.<br> The visual renderings were generated in 0.08 msec for a 23 × 23 output image and in 0.17 ms for a 45 × 45 output image.<br> Through visualization, this study (1) demonstrates that the ML visual output augments the prospects for a more accurate diagnosis and (2) highlights why multiclass classification and regression analysis are incredibly challenging.<br> An online survey was conducted to gauge this visualization platform&#39;s merits and obtain valuable feedback from users.<br> All implementation codes are shared online on GitHub.</p><p>CONCLUSION:<br> This approach makes it possible to visualize the many nuances that lead to a specific classification or prediction in the disease trajectory, all in context to multimodal measurements taken at baseline.<br> This ML model can serve as a multiclass classification and prediction model while reinforcing the diagnosis and prognosis capabilities by including a visualization platform.</p><p>(10.1016/j.artmed.2023.102543)</p><h2 id="comparing-machine-learning-derived-mri-based-and-blood-based-neurodegeneration-biomarkers-in-predicting-syndromal-conversion-in-early-ad" tabindex="-1"><a class="header-anchor" href="#comparing-machine-learning-derived-mri-based-and-blood-based-neurodegeneration-biomarkers-in-predicting-syndromal-conversion-in-early-ad"><span>Comparing machine learning-derived MRI-based and blood-based neurodegeneration biomarkers in predicting syndromal conversion in early AD.</span></a></h2><p>INTRODUCTION:<br> We compared the machine learning-derived, MRI-based Alzheimer&#39;s disease (AD) resemblance atrophy index (AD-RAI) with plasma neurofilament light chain (NfL) level in predicting conversion of early AD among cognitively unimpaired (CU) and mild cognitive impairment (MCI) subjects.</p><p>METHODS:<br> We recruited participants from the Alzheimer&#39;s Disease Neuroimaging Initiative (ADNI) who had the following data:<br> clinical features (age, gender, education, Montreal Cognitive Assessment [MoCA]), structural MRI, plasma biomarkers (p-tau(181) , NfL), cerebrospinal fluid biomarkers (CSF) (Aβ42, p-tau(181) ), and apolipoprotein E (APOE)ε4 genotype.<br> We defined AD using CSF Aβ42 (A+) and p-tau(181) (T+).<br> We defined conversion (C+) if a subject progressed to the next syndromal stage within 4 years.</p><p>RESULTS:<br> Of 589 participants, 96 (16.3%) were A+T+C+.<br> AD-RAI performed better than plasma NfL when added on top of clinical features, plasma p-tau(181) , and APOEε4 genotype (area under the curve [AUC] = 0.832 vs.<br> AUC = 0.650 among CU, AUC = 0.853 vs.<br> AUC = 0.805 among MCI) in predicting A+T+C+.</p><p>DISCUSSION:<br> AD-RAI outperformed plasma NfL in predicting syndromal conversion of early AD.</p><p>HIGHLIGHTS:<br> AD-RAI outperformed plasma NfL in predicting syndromal conversion among early AD.<br> AD-RAI showed better metrics than volumetric hippocampal measures in predicting syndromal conversion.<br> Combining clinical features, plasma p-tau(181) and apolipoprotein E (APOE) with AD-RAI is the best model for predicting syndromal conversion.</p><p>(10.1002/alz.13083)</p><h2 id="comparison-of-machine-learning-based-approaches-to-predict-the-conversion-to-alzheimer-s-disease-from-mild-cognitive-impairment" tabindex="-1"><a class="header-anchor" href="#comparison-of-machine-learning-based-approaches-to-predict-the-conversion-to-alzheimer-s-disease-from-mild-cognitive-impairment"><span>Comparison of Machine Learning-based Approaches to Predict the Conversion to Alzheimer&#39;s Disease from Mild Cognitive Impairment.</span></a></h2><p>In Mild Cognitive Impairment (MCI), identifying a high risk of conversion to Alzheimer&#39;s Disease Dementia (AD) is a primary goal for patient management.<br> Machine Learning (ML) algorithms are widely employed to pursue data-driven diagnostic and prognostic goals.<br> An agreement on the stability of these algorithms -when applied to different biomarkers and other conditions-is far from being reached.<br> In this study, we compared the different prognostic performances of three supervised ML algorithms fed with multimodal biomarkers of MCI subjects obtained from the Alzheimer&#39;s Disease Neuroimaging Initiative (ADNI) database.<br> Random Forest, Gradient Boosting, and eXtreme Gradient Boosting algorithms predict MCI conversion to AD.<br> They can also be simultaneously employed -with the voting procedure-to improve predictivity.<br> AD prediction accuracy is influenced by the nature of the data (i.e., neuropsychological test scores, cerebrospinal fluid AD-related proteins and APOEε4, cerebral structural MRI (sMRI) data).<br> In our study, independent of the applied ML algorithms, sMRI data showed the lowest accuracy (0.79) compared to other classes.<br> Multimodal data were helpful in the algorithms&#39; performances by combining clinical and biological measures.<br> Accordingly, using the three ML algorithms, the highest accuracy (0.90) was reached by employing neuropsychological and AD-related biomarkers.<br> Finally, the feature selection procedure indicated that the most critical variables in the respective classes were the ADAS-Cog-13 scale, the medial temporal lobe and hippocampus atrophy, and the ratio between phosphorylated Tau and Aβ42 proteins.<br> In conclusion, our data support the notion that using multiple ML algorithms and multimodal biomarkers helps make more accurate and solid predictions.<br> (10.1016/j.neuroscience.2023.01.029)</p><h2 id="identification-of-hub-proteins-in-cerebrospinal-fluid-as-potential-biomarkers-of-alzheimer-s-disease-by-integrated-bioinformatics" tabindex="-1"><a class="header-anchor" href="#identification-of-hub-proteins-in-cerebrospinal-fluid-as-potential-biomarkers-of-alzheimer-s-disease-by-integrated-bioinformatics"><span>Identification of hub proteins in cerebrospinal fluid as potential biomarkers of Alzheimer&#39;s disease by integrated bioinformatics</span></a></h2><p>BACKGROUND:<br> Alzheimer&#39;s disease (AD) is a heterogeneous neurodegenerative disease with complex pathophysiology.<br> Therefore, the identification of novel effective fluid biomarkers is essential for Alzheimer&#39;s disease diagnosis and drug development.<br> This study aimed to identify potential candidate hub proteins in cerebrospinal fluid for precise Alzheimer&#39;s disease diagnosis using bioinformatics methods.<br> METHODS:<br> A total of 29 co-significant differentially expressed proteins were identified by differential protein expression analysis in four different cohorts.<br> Functional enrichment analysis revealed that most of these proteins were enriched in pathways related to glycometabolism.<br> Using the Least Absolute Shrinkage and Selection Operator (LASSO) and random forest feature selection methods, six hub proteins [14-3-3 protein zeta/delta (YWHAZ), SPARC-related modular calcium-binding protein 1 (SMOC1), aldolase A (ALDOA), pyruvate kinase isoenzyme type M2 (PKM), chitinase-3-like protein 1 (CHI3L1), and secreted phosphoprotein 1 (SPP1)] were identified.<br> RESULTS:<br> These six hub proteins were upregulated in the cerebrospinal fluid of patients with Alzheimer&#39;s disease compared with cognitively unimpaired control individuals.<br> Meanwhile, SMOC1, ALDOA, and PKM were specifically upregulated in the cerebrospinal fluid of patients with Alzheimer&#39;s disease but not in other neurodegenerative diseases.<br> Build AD diagnostic models showed that a single hub protein or six hub proteins combination had an excellent ability to discriminate Alzheimer&#39;s disease.<br> CONCLUSIONS:<br> In conclusion, our study suggests that these identified hub proteins, which are related to glycometabolism, may be potential biomarkers for further basic and clinical research in Alzheimer&#39;s disease.<br> (10.1007/s00415-022-11476-2)</p><h2 id="association-of-longitudinal-cognitive-decline-with-diffusion-mri-in-gray-matter-amyloid-and-tau-deposition" tabindex="-1"><a class="header-anchor" href="#association-of-longitudinal-cognitive-decline-with-diffusion-mri-in-gray-matter-amyloid-and-tau-deposition"><span>Association of longitudinal cognitive decline with diffusion MRI in Gray Matter, Amyloid, and Tau deposition.</span></a></h2><p>Extracellular amyloid plaques in gray matter are the earliest pathological marker for Alzheimer&#39;s disease (AD), followed by abnormal tau protein accumulation.<br> The link between diffusion changes in gray matter, amyloid and tau pathology, and cognitive decline is not well understood.<br> We first performed cross-sectional analyses on T1-weighted imaging, diffusion MRI, and amyloid and tau PETs from the ADNI 2/3 database.<br> We evaluated cortical volume, free-water, fractional anisotropy (FA), and amyloid and tau SUVRs in 171 cognitively normal, 103 MCI, and 44 AD individuals.<br> When the 3 groups were combined, increasing amyloid burden was associated with reduced extracellular free-water in the entorhinal cortex and hippocampus in those with amyloid-negative status whereas increasing tau burden was associated with increased extracellular free-water regardless of amyloid status.<br> Next, we found that for the MCI subjects, diffusion measures (free-water, FA) alone predicted MMSE score 2 years later with a high r-square value (87%), as compared to tau SUVRs (27%), T1 volume (36%), and amyloid SUVRs (75%).<br> Diffusion measures represent a potent non-invasive marker for predicting cognitive decline.<br> (10.1016/j.neurobiolaging.2022.10.013)</p><h2 id="ribosomal-proteins-are-blood-biomarkers-and-associated-with-cd4-t-cell-activation-in-alzheimer-s-disease-a-study-based-on-machine-learning-strategies-and-scrna-seq-data-validation" tabindex="-1"><a class="header-anchor" href="#ribosomal-proteins-are-blood-biomarkers-and-associated-with-cd4-t-cell-activation-in-alzheimer-s-disease-a-study-based-on-machine-learning-strategies-and-scrna-seq-data-validation"><span>Ribosomal proteins are blood biomarkers and associated with CD4+ T cell activation in Alzheimer&#39;s disease: a study based on machine learning strategies and scRNA-Seq data validation.</span></a></h2><p>BACKGROUND:<br> Alzheimer&#39;s disease (AD) is a widespread neurodegenerative disease that primarily affects the elderly.<br> Unfortunately, the lack of convenient early diagnostic tools makes it difficult to intervene and treat the disease during its initial stages.<br> METHODS:<br> We obtained four bulk and single-cell RNA-sequencing peripheral blood samples related to AD from public databases.<br> Using Boruta and LASSO machine learning algorithms, we screened the signature genes and constructed a diagnostic model using lightGBM.<br> The model was further validated in a test cohort.<br> Additionally, we extracted hub biomarkers using the protein-protein interactions method and validated them in a single-cell RNA-seq dataset.<br> RESULTS:<br> Our analysis revealed the identification of 37 AD-related peripheral blood signature genes, with their main enrichment in ribosome-related biological functions.<br> Four core biomarkers, RPL24, RPL5, RPS27A, and RPS4X, were identified and exhibited good diagnostic power in the testing cohort.<br> Immune infiltration analysis revealed a higher proportion of CD4+ T cells in AD patients&#39; peripheral blood compared to healthy controls, with a negative correlation with the four ribosome-associated core genes.<br> Validation in a single-cell RNA-seq dataset confirmed these findings.<br> CONCLUSIONS:<br> Ribosomal family proteins have the potential to serve as biomarkers for the diagnosis and treatment of AD, and are associated with CD4+ T cell activation.</p><h2 id="machine-learning-selection-of-most-predictive-brain-proteins-suggests-role-of-sugar-metabolism-in-alzheimer-s-disease" tabindex="-1"><a class="header-anchor" href="#machine-learning-selection-of-most-predictive-brain-proteins-suggests-role-of-sugar-metabolism-in-alzheimer-s-disease"><span>Machine Learning Selection of Most Predictive Brain Proteins Suggests Role of Sugar Metabolism in Alzheimer&#39;s Disease.</span></a></h2><p>BACKGROUND:<br> The complex and not yet fully understood etiology of Alzheimer&#39;s disease (AD) shows important proteopathic signs which are unlikely to be linked to a single protein.<br> However, protein subsets from deep proteomic datasets can be useful in stratifying patient risk, identifying stage dependent disease markers, and suggesting possible disease mechanisms.<br> OBJECTIVE:<br> The objective was to identify protein subsets that best classify subjects into control, asymptomatic Alzheimer&#39;s disease (AsymAD), and AD.<br> METHODS:<br> Data comprised 6 cohorts;<br> 620 subjects;<br> 3,334 proteins.<br> Brain tissue-derived predictive protein subsets for classifying AD, AsymAD, or control were identified and validated with label-free quantification and machine learning.<br> RESULTS:<br> A 29-protein subset accurately classified AD (AUC = 0.94).<br> However, an 88-protein subset best predicted AsymAD (AUC = 0.92) or Control (AUC = 0.92) from AD (AUC = 0.98).<br> AD versus Control:<br> APP, DHX15, NRXN1, PBXIP1, RABEP1, STOM, and VGF.<br> AD versus AsymAD:<br> ALDH1A1, BDH2, C4A, FABP7, GABBR2, GNAI3, PBXIP1, and PRKAR1B.<br> AsymAD versus Control:<br> APP, C4A, DMXL1, EXOC2, PITPNB, RABEP1, and VGF.<br> Additional predictors:<br> DNAJA3, PTBP2, SLC30A9, VAT1L, CROCC, PNP, SNCB, ENPP6, HAPLN2, PSMD4, and CMAS.<br> CONCLUSION:<br> Biomarkers were dynamically separable across disease stages.<br> Predictive proteins were significantly enriched to sugar metabolism.<br> (10.3233/JAD-220683)</p><h2 id="pinnet-a-deep-neural-network-with-pathway-prior-knowledge-for-alzheimer-s-disease" tabindex="-1"><a class="header-anchor" href="#pinnet-a-deep-neural-network-with-pathway-prior-knowledge-for-alzheimer-s-disease"><span>PINNet: a deep neural network with pathway prior knowledge for Alzheimer&#39;s disease.</span></a></h2><p>INTRODUCTION:<br> Identification of Alzheimer&#39;s Disease (AD)-related transcriptomic signatures from blood is important for early diagnosis of the disease.<br> Deep learning techniques are potent classifiers for AD diagnosis, but most have been unable to identify biomarkers because of their lack of interpretability.<br> METHODS:<br> To address these challenges, we propose a pathway information-based neural network (PINNet) to predict AD patients and analyze blood and brain transcriptomic signatures using an interpretable deep learning model.<br> PINNet is a deep neural network (DNN) model with pathway prior knowledge from either the Gene Ontology or Kyoto Encyclopedia of Genes and Genomes databases.<br> Then, a backpropagation-based model interpretation method was applied to reveal essential pathways and genes for predicting AD.<br> RESULTS:<br> The performance of PINNet was compared with a DNN model without a pathway.<br> Performances of PINNet outperformed or were similar to those of DNN without a pathway using blood and brain gene expressions, respectively.<br> Moreover, PINNet considers more AD-related genes as essential features than DNN without a pathway in the learning process.<br> Pathway analysis of protein-protein interaction modules of highly contributed genes showed that AD-related genes in blood were enriched with cell migration, PI3K-Akt, MAPK signaling, and apoptosis in blood.<br> The pathways enriched in the brain module included cell migration, PI3K-Akt, MAPK signaling, apoptosis, protein ubiquitination, and t-cell activation.<br> DISCUSSION:<br> By integrating prior knowledge about pathways, PINNet can reveal essential pathways related to AD.<br> The source codes are available at <a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.<br> com/DMCB-GIST/PINNet.<br> (10.3389/fnagi.2023.1126156)</p><h2 id="identification-of-biomarkers-differentiating-alzheimer-s-disease-from-other-neurodegenerative-diseases-by-integrated-bioinformatic-analysis-and-machine-learning-strategies" tabindex="-1"><a class="header-anchor" href="#identification-of-biomarkers-differentiating-alzheimer-s-disease-from-other-neurodegenerative-diseases-by-integrated-bioinformatic-analysis-and-machine-learning-strategies"><span>Identification of biomarkers differentiating Alzheimer&#39;s disease from other neurodegenerative diseases by integrated bioinformatic analysis and machine-learning strategies.</span></a></h2><p>BACKGROUND:<br> Alzheimer&#39;s disease (AD) is the most common neurodegenerative disease, imposing huge mental and economic burdens on patients and society.<br> The specific molecular pathway(s) and biomarker(s) that distinguish AD from other neurodegenerative diseases and reflect the disease progression are still not well studied.<br> METHODS:<br> Four frontal cortical datasets of AD were integrated to conduct differentially expressed genes (DEGs) and functional gene enrichment analyses.<br> The transcriptional changes after the integrated frontal cortical datasets subtracting the cerebellar dataset of AD were further compared with frontal cortical datasets of frontotemporal dementia and Huntingdon&#39;s disease to identify AD-frontal-associated gene expression.<br> Integrated bioinformatic analysis and machine-learning strategies were applied for screening and determining diagnostic biomarkers, which were further validated in another two frontal cortical datasets of AD by receiver operating characteristic (ROC) curves.<br> RESULTS:<br> Six hundred and twenty-six DEGs were identified as AD frontal associated, including 580 downregulated genes and 46 upregulated genes.<br> The functional enrichment analysis revealed that immune response and oxidative stress were enriched in AD patients.<br> Decorin (DCN) and regulator of G protein signaling 1 (RGS1) were screened as diagnostic biomarkers in distinguishing AD from frontotemporal dementia and Huntingdon&#39;s disease of AD.<br> The diagnostic effects of DCN and RGS1 for AD were further validated in another two datasets of AD:<br> the areas under the curve (AUCs) reached 0.8148 and 0.8262 in GSE33000, and 0.8595 and 0.8675 in GSE44770.<br> There was a better value for AD diagnosis when combining performances of DCN and RGS1 with the AUCs of 0.863 and 0.869.<br> Further, DCN mRNA level was correlated to CDR (Clinical Dementia Rating scale) score (r = 0.5066, p = 0.0058) and Braak staging (r = 0.3348, p = 0.0549).<br> CONCLUSION:<br> DCN and RGS1 associated with the immune response may be useful biomarkers for diagnosing AD and distinguishing the disease from frontotemporal dementia and Huntingdon&#39;s disease.<br> DCN mRNA level reflects the development of the disease.<br> (10.3389/fnmol.2023.1152279)</p><h2 id="identification-of-diagnostic-biomarkers-in-alzheimer-s-disease-by-integrated-bioinformatic-analysis-and-machine-learning-strategies" tabindex="-1"><a class="header-anchor" href="#identification-of-diagnostic-biomarkers-in-alzheimer-s-disease-by-integrated-bioinformatic-analysis-and-machine-learning-strategies"><span>Identification of diagnostic biomarkers in Alzheimer&#39;s disease by integrated bioinformatic analysis and machine learning strategies.</span></a></h2><p>BACKGROUND:<br> Alzheimer&#39;s disease (AD) is the most prevalent form of dementia, and is becoming one of the most burdening and lethal diseases.<br> More useful biomarkers for diagnosing AD and reflecting the disease progression are in need and of significance.<br> METHODS:<br> The integrated bioinformatic analysis combined with machine-learning strategies was applied for exploring crucial functional pathways and identifying diagnostic biomarkers of AD.<br> Four datasets (GSE5281, GSE131617, GSE48350, and GSE84422) with samples of AD frontal cortex are integrated as experimental datasets, and another two datasets (GSE33000 and GSE44772) with samples of AD frontal cortex were used to perform validation analyses.<br> Functional Correlation enrichment analyses were conducted based on Gene ontology (GO), Kyoto Encyclopedia of Genes and Genomes (KEGG), and the Reactome database to reveal AD-associated biological functions and key pathways.<br> Four models were employed to screen the potential diagnostic biomarkers, including one bioinformatic analysis of Weighted gene co-expression network analysis (WGCNA)and three machine-learning algorithms:<br> Least absolute shrinkage and selection operator (LASSO), support vector machine-recursive feature elimination (SVM-RFE) and random forest (RF) analysis.<br> The correlation analysis was performed to explore the correlation between the identified biomarkers with CDR scores and Braak staging.<br> RESULTS:<br> The pathways of the immune response and oxidative stress were identified as playing a crucial role during AD.<br> Thioredoxin interacting protein (TXNIP), early growth response 1 (EGR1), and insulin-like growth factor binding protein 5 (IGFBP5) were screened as diagnostic markers of AD.<br> The diagnostic efficacy of TXNIP, EGR1, and IGFBP5 was validated with corresponding AUCs of 0.857, 0.888, and 0.856 in dataset GSE33000, 0.867, 0.909, and 0.841 in dataset GSE44770.<br> And the AUCs of the combination of these three biomarkers as a diagnostic tool for AD were 0.954 and 0.938 in the two verification datasets.<br> CONCLUSION:<br> The pathways of immune response and oxidative stress can play a crucial role in the pathogenesis of AD.<br> TXNIP, EGR1, and IGFBP5 are useful biomarkers for diagnosing AD and their mRNA level may reflect the development of the disease by correlation with the CDR scores and Breaking staging.<br> (10.3389/fnagi.2023.1169620)</p><h2 id="exploring-the-interaction-between-t-cell-antigen-receptor-related-genes-and-mapt-or-ache-using-integrated-bioinformatics-analysis" tabindex="-1"><a class="header-anchor" href="#exploring-the-interaction-between-t-cell-antigen-receptor-related-genes-and-mapt-or-ache-using-integrated-bioinformatics-analysis"><span>Exploring the interaction between T-cell antigen receptor-related genes and MAPT or ACHE using integrated bioinformatics analysis.</span></a></h2><p>Alzheimer&#39;s disease (AD) is a neurodegenerative disease that primarily occurs in elderly individuals with cognitive impairment.<br> Although extracellularβ-amyloid (Aβ) accumulation and tau protein hyperphosphorylation are considered to be leading causes of AD, the molecular mechanism of AD remains unknown.<br> Therefore, in this study, we aimed to explore potential biomarkers of AD.<br> Next-generation sequencing (NGS) datasets, GSE173955 and GSE203206, were collected from the Gene Expression Omnibus (GEO) database.<br> Analysis of differentially expressed genes (DEGs), gene ontology (GO) functional enrichment, Kyoto Encyclopedia of Genes and Genomes (KEGG) pathway enrichment, and protein-protein networks were performed to identify genes that are potentially associated with AD.<br> Analysis of the DEG based protein-protein interaction (PPI) network using Cytoscape indicated that neuroinflammation and T-cell antigen receptor (TCR)-associated genes (LCK, ZAP70, and CD44) were the top three hub genes.<br> Next, we validated these three hub genes in the AD database and utilized two machine learning models from different AD datasets (GSE15222) to observe their general relationship with AD.<br> Analysis using the random forest classifier indicated that accuracy (78%) observed using the top three genes as inputs differed only slightly from that (84%) observed using all genes as inputs.<br> Furthermore, another data set, GSE97760, which was analyzed using our novel eigenvalue decomposition method, indicated that the top three hub genes may be involved in tauopathies associated with AD, rather than Aβ pathology.<br> In addition, protein-protein docking simulation revealed that the top hub genes could form stable binding sites with acetylcholinesterase (ACHE).<br> This suggests a potential interaction between hub genes and ACHE, which plays an essential role in the development of anti-AD drug design.<br> Overall, the findings of this study, which systematically analyzed several AD datasets, illustrated that LCK, ZAP70, and CD44 may be used as AD biomarkers.<br> We also established a robust prediction model for classifying patients with AD.<br> (10.3389/fneur.2023.1129470)</p><h2 id="heavy-metals-and-essential-metals-are-associated-with-cerebrospinal-fluid-biomarkers-of-alzheimer-s-disease" tabindex="-1"><a class="header-anchor" href="#heavy-metals-and-essential-metals-are-associated-with-cerebrospinal-fluid-biomarkers-of-alzheimer-s-disease"><span>Heavy Metals and Essential Metals Are Associated with Cerebrospinal Fluid Biomarkers of Alzheimer&#39;s Disease.</span></a></h2><p>Various metals have been associated with the pathogenesis of Alzheimer&#39;s disease (AD), principally heavy metals that are environmental pollutants (such as As, Cd, Hg, and Pb) and essential metals whose homeostasis is disturbed in AD (such as Cu, Fe, and Zn).<br> Although there is evidence of the involvement of these metals in AD, further research is needed on their mechanisms of toxicity.<br> To further assess the involvement of heavy and essential metals in AD pathogenesis, we compared cerebrospinal fluid (CSF) AD biomarkers to macro-and microelements measured in CSF and plasma.<br> We tested if macro-and microelements&#39; concentrations (heavy metals (As, Cd, Hg, Ni, Pb, and Tl), essential metals (Na, Mg, K, Ca, Fe, Co, Mn, Cu, Zn, and Mo), essential non-metals (B, P, S, and Se), and other non-essential metals (Al, Ba, Li, and Sr)) are associated with CSF AD biomarkers that reflect pathological changes in the AD brain (amyloidβ(1-42), total tau, phosphorylated tau isoforms, NFL, S100B, VILIP-1, YKL-40, PAPP-A, and albumin).<br> We used inductively coupled plasma mass spectroscopy (ICP-MS) to determine macro-and microelements in CSF and plasma, and enzyme-linked immunosorbent assays (ELISA) to determine protein biomarkers of AD in CSF.<br> This study included 193 participants (124 with AD, 50 with mild cognitive impairment, and 19 healthy controls).<br> Simple correlation, as well as machine learning algorithms (redescription mining and principal component analysis (PCA)), demonstrated that levels of heavy metals (As, Cd, Hg, Ni, Pb, and Tl), essential metals (Ca, Co, Cu, Fe, Mg, Mn, Mo, Na, K, and Zn), and essential non-metals (P, S, and Se) are positively associated with CSF phosphorylated tau isoforms, VILIP-1, S100B, NFL, and YKL-40 in AD.<br> (10.3390/ijms24010467)</p><h2 id="machine-learning-based-classification-of-subjective-cognitive-decline-mild-cognitive-impairment-and-alzheimer-s-dementia-using-neuroimage-and-plasma-biomarkers" tabindex="-1"><a class="header-anchor" href="#machine-learning-based-classification-of-subjective-cognitive-decline-mild-cognitive-impairment-and-alzheimer-s-dementia-using-neuroimage-and-plasma-biomarkers"><span>Machine Learning-Based Classification of Subjective Cognitive Decline, Mild Cognitive Impairment, and Alzheimer&#39;s Dementia Using Neuroimage and Plasma Biomarkers.</span></a></h2><p>Alzheimer&#39;s disease (AD) progresses relentlessly from the preclinical to the dementia stage.<br> The process begins decades before the diagnosis of dementia.<br> Therefore, it is crucial to detect early manifestations to prevent cognitive decline.<br> Recent advances in artificial intelligence help tackle the complex high-dimensional data encountered in clinical decision-making.<br> In total, we recruited 206 subjects, including 69 cognitively unimpaired, 40 subjective cognitive decline (SCD), 34 mild cognitive impairment (MCI), and 63 AD dementia (ADD).<br> We included 3 demographic, 1 clinical, 18 brain-image, and 3 plasma biomarker (Aß(1-42), Aß(1-40), and tau protein) features.<br> We employed the linear discriminant analysis method for feature extraction to make data more distinguishable after dimension reduction.<br> The sequential forward selection method was used for feature selection to identify the 12 best features for machine learning classifiers.<br> We used both random forest and support vector machine as classifiers.<br> The area under the receiver operative curve (AUROC) was close to 0.9 between diseased (combining ADD and MCI) and the controls.<br> AUROC was higher than 0.85 between SCD and controls, 0.90 between MCI and SCD, and above 0.85 between ADD and MCI.<br> We can differentiate between adjacent phases of the AD spectrum with blood biomarkers and brain MR images with the help of machine learning algorithms.<br> (10.1021/acschemneuro.2c00255)</p><h2 id="integrated-analyses-of-brain-and-platelet-omics-reveal-their-common-altered-and-driven-molecules-in-alzheimer-s-disease" tabindex="-1"><a class="header-anchor" href="#integrated-analyses-of-brain-and-platelet-omics-reveal-their-common-altered-and-driven-molecules-in-alzheimer-s-disease"><span>Integrated analyses of brain and platelet omics reveal their common altered and driven molecules in Alzheimer&#39;s disease.</span></a></h2><p>Platelets may serve as a perfect peripheral source for exploring diagnostic biomarkers for Alzheimer&#39;s disease (AD);<br> however, the molecular linkage between platelet and the brain is missing.<br> To find the common altered and driving molecules in both brain and the platelet, we performed an integrated analysis of our platelet omics and brain omics reported in the literature, and analyzed their correlations with AD-specific pathology and cognitive impairment.<br> By integrating the gene and protein expression profiles from 269 AD patients, we deduced 239 differentially expressed proteins (DEPs) appeared in both brain and the platelet, and 70.3% of them had consistent changes.<br> Further analysis demonstrated that the altered brain and peripheral regulations were pinpointed into 10 imbalanced pathways.<br> We also found that 117 DEPs, including ADAM10, were closely associated to the AD-specificβ-amyloid and tau pathologies;<br> and the changes of IDH3B and RTN1 had a potential diagnostic value for cognitive impairment analyzed by machine learning.<br> Finally, we identified that HMOX2 and SERPINA3 could serve as driving molecules in neurodegeneration, and they were increased and decreased in AD patients, respectively.<br> Together, this integrated brain and platelet omics provides a valuable resource for establishing efficient peripheral diagnostic biomarkers and potential therapeutic targets for AD.<br> (10.1002/mco2.180)</p><h2 id="interpretable-classification-of-tauopathies-with-a-convolutional-neural-network-pipeline-using-transfer-learning-and-validation-against-post-mortem-clinical-cases-of-alzheimer-s-disease-and-progressive-supranuclear-palsy" tabindex="-1"><a class="header-anchor" href="#interpretable-classification-of-tauopathies-with-a-convolutional-neural-network-pipeline-using-transfer-learning-and-validation-against-post-mortem-clinical-cases-of-alzheimer-s-disease-and-progressive-supranuclear-palsy"><span>Interpretable Classification of Tauopathies with a Convolutional Neural Network Pipeline Using Transfer Learning and Validation against Post-Mortem Clinical Cases of Alzheimer&#39;s Disease and Progressive Supranuclear Palsy.</span></a></h2><p>Neurodegenerative diseases, tauopathies, constitute a serious global health problem.<br> The etiology of these diseases is unclear and an increase in their incidence has been projected in the next 30 years.<br> Therefore, the study of the molecular mechanisms that might stop these neurodegenerative processes is very relevant.<br> Classification of neurodegenerative diseases using Machine and Deep Learning algorithms has been widely studied for medical imaging such as Magnetic Resonance Imaging.<br> However, post-mortem immunofluorescence imaging studies of the brains of patients have not yet been used for this purpose.<br> These studies may represent a valuable tool for monitoring aberrant chemical changes or pathological post-translational modifications of the Tau polypeptide.<br> We propose a Convolutional Neural Network pipeline for the classification of Tau pathology of Alzheimer&#39;s disease and Progressive Supranuclear Palsy by analyzing post-mortem immunofluorescence images with different Tau biomarkers performed with models generated with the architecture ResNet-IFT using Transfer Learning.<br> These models&#39; outputs were interpreted with interpretability algorithms such as Guided Grad-CAM and Occlusion Analysis.<br> To determine the best classifier, four different architectures were tested.<br> We demonstrated that our design was able to classify diseases with an accuracy of 98.41% on average whilst providing an interpretation concerning the proper classification involving different structural patterns in the immunoreactivity of the Tau protein in NFTs present in the brains of patients with Progressive Supranuclear Palsy and Alzheimer&#39;s disease.<br> (10.3390/cimb44120406)</p><h2 id="prediction-of-amyloid-pet-positivity-via-machine-learning-algorithms-trained-with-edta-based-blood-amyloid-β-oligomerization-data" tabindex="-1"><a class="header-anchor" href="#prediction-of-amyloid-pet-positivity-via-machine-learning-algorithms-trained-with-edta-based-blood-amyloid-β-oligomerization-data"><span>Prediction of amyloid PET positivity via machine learning algorithms trained with EDTA-based blood amyloid-β oligomerization data.</span></a></h2><p>BACKGROUND:<br> The tendency of amyloid-β to form oligomers in the blood as measured with Multimer Detection System-Oligomeric Amyloid-β (MDS-OAβ) is a valuable biomarker for Alzheimer&#39;s disease and has been verified with heparin-based plasma.<br> The objective of this study was to evaluate the performance of ethylenediaminetetraacetic acid (EDTA)-based MDS-OAβ and to develop machine learning algorithms to predict amyloid positron emission tomography (PET) positivity.<br> METHODS:<br> The performance of EDTA-based MDS-OAβ in predicting PET positivity was evaluated in 312 individuals with various machine learning models.<br> The models with various combinations of features (i.e., MDS-OAβ level, age, apolipoprotein E4 alleles, and Mini-Mental Status Examination [MMSE] score) were tested 50 times on each dataset.<br> RESULTS:<br> The random forest model best-predicted amyloid PET positivity based on MDS-OAβ combined with other features with an accuracy of 77.14  ± 4.21% and an F1 of 85.44 ± 3.10%.<br> The order of significance of predictive features was MDS-OAβ, MMSE, Age, and APOE.<br> The Support Vector Machine using the MDS-OAβ value only showed an accuracy of 71.09 ± 3.27% and F-1 value of 80.18 ± 2.70%.<br> CONCLUSIONS:<br> The Random Forest model using EDTA-based MDS-OAβ combined with the MMSE and apolipoprotein E status can be used to prescreen for amyloid PET positivity.<br> (10.1186/s12911-022-02024-z)</p><h2 id="willis-lecture-biomarkers-for-inflammatory-white-matter-injury-in-binswanger-disease-provide-pathways-to-precision-medicine" tabindex="-1"><a class="header-anchor" href="#willis-lecture-biomarkers-for-inflammatory-white-matter-injury-in-binswanger-disease-provide-pathways-to-precision-medicine"><span>Willis Lecture: Biomarkers for Inflammatory White Matter Injury in Binswanger Disease Provide Pathways to Precision Medicine.</span></a></h2><p>Binswanger disease is the small vessel form of vascular cognitive impairment and dementia.<br> Deposition of Alzheimer disease proteins can begin in midlife and progress slowly, whereas aging of the vasculature also can begin in midlife, continuing to progress into old age, making mixed dementia the most common type of dementia.<br> Biomarkers facilitate the early diagnosis of dementias.<br> It is possible to diagnose mixed dementia before autopsy with biomarkers for vascular disease derived from diffusor tensor images on magnetic resonance imaging and Alzheimer disease proteins, Aβ (amyloidβ), and phosphorylated tau, in cerebrospinal fluid or in brain with positron emission tomography.<br> The presence of vascular disease accelerates cognitive decline.<br> Both misfolded proteins and vascular disease promote inflammation, which can be detected in cerebrospinal fluid by the presence of MMPs (matrix metalloproteinases), angiogenic growth factors, and cytokines.<br> MMPs disrupt the blood-brain barrier and break down myelin, producing Binswanger disease&#39;s 2 main pathological features.<br> Advances in detecting biomarkers in plasma will provide early detection of dementia and aided by machine learning and artificial intelligence, will enhance diagnosis and form the basis for early treatments.<br> (10.1161/STROKEAHA.122.039211)</p><h2 id="bioinformatics-analysis-of-diagnostic-biomarkers-for-alzheimer-s-disease-in-peripheral-blood-based-on-sex-differences-and-support-vector-machine-algorithm" tabindex="-1"><a class="header-anchor" href="#bioinformatics-analysis-of-diagnostic-biomarkers-for-alzheimer-s-disease-in-peripheral-blood-based-on-sex-differences-and-support-vector-machine-algorithm"><span>Bioinformatics analysis of diagnostic biomarkers for Alzheimer&#39;s disease in peripheral blood based on sex differences and support vector machine algorithm.</span></a></h2><p>BACKGROUND:<br> The prevalence of Alzheimer&#39;s disease (AD) varies based on gender.<br> Due to the lack of early stage biomarkers, most of them are diagnosed at the terminal stage.<br> This study aimed to explore sex-specific signaling pathways and identify diagnostic biomarkers of AD.<br> METHODS:<br> Microarray dataset for blood was obtained from the Gene Expression Omnibus (GEO) database of GSE63060 to conduct differentially expressed genes (DEGs) analysis by R software limma.<br> Gene Ontology (GO) analysis, Kyoto Encyclopedia of Genes and Genomes (KEGG) pathway analysis and Gene set enrichment analysis (GSEA) were conducted.<br> Immune checkpoint gene expression was compared between females and males.<br> Using CytoHubba, we identified hub genes in a protein-protein interaction network (PPI).<br> Then, we evaluated their distinct effectiveness using unsupervised hierarchical clustering.<br> Support vector machine (SVM) and ten-fold cross-validation were used to further verify these biomarkers.<br> Lastly, we confirmed our findings by using another independent dataset.<br> RESULTS:<br> A total of 37 female-specific DEGs and 27 male-specific DEGs were identified from GSE63060 datasets.<br> Analyses of enrichment showed that female-specific DEGs primarily focused on energy metabolism, while male-specific DEGs mostly involved in immune regulation.<br> Three immune-checkpoint-relevant genes dysregulated in males.<br> In females, however, these eight genes were not differentially expressed.<br> SNRPG, RPS27A, COX7A2, ATP5PO, LSM3, COX7C, PFDN5, HINT1, PSMA6, RPS3A and RPL31 were regarded as hub genes for females, while SNRPG, RPL31, COX7C, RPS27A, RPL35A, RPS3A, RPS20 and PFDN5 were regarded as hub genes for males.<br> Thirteen hub genes mentioned above was significantly lower in both AD and mild cognitive impairment (MCI).<br> The diagnostic model of 15-marker panel (13 hub genes with sex and age) was developed.<br> Both the training dataset and the independent validation dataset have area under the curve (AUC) with a high value (0.919, 95%CI 0.901-0.929 and 0.803, 95%CI 0.789-0.826).<br> Based on GSEA for hub genes, they were associated with some aspects of AD pathogenesis.<br> CONCLUSION:<br> DEGs in males and females contribute differently to AD pathogenesis.<br> Algorithms combining blood-based biomarkers may improve AD diagnostic accuracy, but large validation studies are needed.<br> (10.1186/s41065-022-00252-x)</p><h2 id="probing-the-proteome-to-explore-potential-correlates-of-increased-alzheimer-s-related-cerebrovascular-disease-in-adults-with-down-syndrome" tabindex="-1"><a class="header-anchor" href="#probing-the-proteome-to-explore-potential-correlates-of-increased-alzheimer-s-related-cerebrovascular-disease-in-adults-with-down-syndrome"><span>Probing the proteome to explore potential correlates of increased Alzheimer&#39;s-related cerebrovascular disease in adults with Down syndrome.</span></a></h2><p>Cerebrovascular disease is associated with symptoms and pathogenesis of Alzheimer&#39;s disease (AD) among adults with Down syndrome (DS).<br> The cause of increased dementia-related cerebrovascular disease in DS is unknown.<br> We explored whether protein markers of neuroinflammation are associated with markers of cerebrovascular disease among adults with DS.<br> Participants from the Alzheimer&#39;s disease in Down syndrome (ADDS) study with magnetic resonance imaging (MRI) scans and blood biomarker data were included.<br> Support vector machine (SVM) analyses examined the relationship of blood-based proteomic biomarkers with MRI-defined cerebrovascular disease among participants characterized as having cognitive decline (n = 36, mean age ± SD = 53 ± 6.2) and as being cognitively stable (n = 78, mean age = 49 ± 6.4).<br> Inflammatory and AD markers were associated with cerebrovascular disease, particularly among symptomatic individuals.<br> The pattern suggested relatively greater inflammatory involvement among cognitively stable individuals and greater AD involvement among those with cognitively decline.<br> The findings help to generate hypotheses that both inflammatory and AD markers are implicated in cerebrovascular disease among those with DS and point to potential mechanistic pathways for further examination.<br> (10.1002/alz.12627)</p><h2 id="biological-determinants-of-blood-based-cytokines-in-the-alzheimer-s-disease-clinical-continuum" tabindex="-1"><a class="header-anchor" href="#biological-determinants-of-blood-based-cytokines-in-the-alzheimer-s-disease-clinical-continuum"><span>Biological determinants of blood-based cytokines in the Alzheimer&#39;s disease clinical continuum.</span></a></h2><p>Converging translational and clinical research strongly indicates that altered immune and inflammatory homeostasis (neuroinflammation) plays a critical pathophysiological role in Alzheimer&#39;s disease (AD), across the clinical continuum.<br> A dualistic role of neuroinflammation may account for a complex biological phenomenon, representing a potential pharmacological target.<br> Emerging blood-based pathophysiological biomarkers, such as cytokines (Cyt) and interleukins (ILs), have been studied as indicators of neuroinflammation in AD.<br> However, inconsistent results have been reported probably due to a lack of standardization of assays with methodological and analytical differences.<br> We used machine-learning and a cross-validation-based statical workflow to explore and analyze the potential impact of key biological factors, such as age, sex, and apolipoprotein-E (APOE) genotype (the major genetic risk factor for late-onset AD) on Cyt.<br> A set of Cyt was selected based on previous literature, and we investigated any potential association in a pooled cohort of cognitively healthy, mild cognitive impairment (MCI), and AD-like dementia patients.<br> We also performed explorative analyses to extrapolate preliminary clinical insights.<br> We found a robust sex effect on IL12 and an APOE-related difference in IL10, with the latter being also related to the presence of advanced cognitive decline.<br> IL1β was the variable most significantly associated with MCI-to-dementia conversion over a 2.5 year-clinical follow-up.<br> Although preliminary, our data support further clinical research to understand whether plasma Cyt may represent reliable and noninvasive tools serving the investigation of neuroimmune and inflammatory dynamics in AD and to foster biomarker-guided pathway-based therapeutic approaches, within the precision medicine development framework.<br> (10.1111/jnc.15686)</p><h2 id="predicting-at-n-pathologies-in-alzheimer-s-disease-from-blood-based-proteomic-data-using-neural-networks" tabindex="-1"><a class="header-anchor" href="#predicting-at-n-pathologies-in-alzheimer-s-disease-from-blood-based-proteomic-data-using-neural-networks"><span>Predicting AT(N) pathologies in Alzheimer&#39;s disease from blood-based proteomic data using neural networks.</span></a></h2><p>BACKGROUND AND OBJECTIVE:<br> Blood-based biomarkers represent a promising approach to help identify early Alzheimer&#39;s disease (AD).<br> Previous research has applied traditional machine learning (ML) to analyze plasma omics data and search for potential biomarkers, but the most modern ML methods based on deep learning has however been scarcely explored.<br> In the current study, we aim to harness the power of state-of-the-art deep learning neural networks (NNs) to identify plasma proteins that predict amyloid, tau, and neurodegeneration (AT[N]) pathologies in AD.<br> METHODS:<br> We measured 3,635 proteins using SOMAscan in 881 participants from the European Medical Information Framework for AD Multimodal Biomarker Discovery study (EMIF-AD MBD).<br> Participants underwent measurements of brain amyloidβ (Aβ) burden, phosphorylated tau (p-tau) burden, and total tau (t-tau) burden to determine their AT(N) statuses.<br> We ranked proteins by their association with Aβ, p-tau, t-tau, and AT(N), and fed the top 100 proteins along with age and apolipoprotein E (APOE) status into NN classifiers as input features to predict these four outcomes relevant to AD.<br> We compared NN performance of using proteins, age, and APOE genotype with performance of using age and APOE status alone to identify protein panels that optimally improved the prediction over these main risk factors.<br> Proteins that improved the prediction for each outcome were aggregated and nominated for pathway enrichment and protein-protein interaction enrichment analysis.<br> RESULTS:<br> Age and APOE alone predicted Aβ, p-tau, t-tau, and AT(N) burden with area under the curve (AUC) scores of 0.748, 0.662, 0.710, and 0.795.<br> The addition of proteins significantly improved AUCs to 0.782, 0.674, 0.734, and 0.831, respectively.<br> The identified proteins were enriched in five clusters of AD-associated pathways including human immunodeficiency virus 1 infection, p53 signaling pathway, and phosphoinositide-3-kinase-protein kinase B/Akt signaling pathway.<br> CONCLUSION:<br> Combined with age and APOE genotype, the proteins identified have the potential to serve as blood-based biomarkers for AD and await validation in future studies.<br> While the NNs did not achieve better scores than the support vector machine model used in our previous study, their performances were likely limited by small sample size.<br> (10.3389/fnagi.2022.1040001)</p><h2 id="discovering-new-peripheral-plasma-biomarkers-to-identify-cognitive-decline-in-type-2-diabetes" tabindex="-1"><a class="header-anchor" href="#discovering-new-peripheral-plasma-biomarkers-to-identify-cognitive-decline-in-type-2-diabetes"><span>Discovering new peripheral plasma biomarkers to identify cognitive decline in type 2 diabetes.</span></a></h2><p>Type 2 diabetes mellitus (T2DM) is an independent risk factor of Alzheimer&#39;s disease (AD), and thus identifying who among the increasing T2DM populations may develop into AD is important for early intervention.<br> By using TMT-labeling coupled high-throughput mass spectrometry, we conducted a comprehensive plasma proteomic analysis in none-T2DM people (Ctrl, n = 30), and the age-/sex-matched T2DM patients with mild cognitive impairment (T2DM-MCI, n = 30) or T2DM without MCI (T2DM-nMCI, n = 25).<br> The candidate biomarkers identified by proteomics and bioinformatics analyses were verified by ELISA, and their diagnostic capabilities were evaluated with machine learning.<br> A total of 53 differentially expressed proteins (DEPs) were identified in T2DM-MCI compared with T2DM-nMCI patients.<br> These DEPs were significantly enriched in multiple biological processes, such as amyloid neuropathies, CNS disorders, and metabolic acidosis.<br> Among the DEPs, alpha-1-antitrypsin (SERPINA1), major viral protein (PRNP), and valosin-containing protein (VCP) showed strong correlation with AD high-risk genes APP, MAPT, APOE, PSEN1, and PSEN2.<br> Also, the levels of PP2A cancer inhibitor (CIP2A), PRNP, corticotropin-releasing factor-binding protein (CRHBP) were significantly increased, while the level of VCP was decreased in T2DM-MCI patients compared with that of the T2DM-nMCI, and these changes were correlated with the Mini-Mental State Examination (MMSE) score.<br> Further machine learning data showed that increases in PRNP, CRHBP, VCP, and rGSK-3β(T/S9) (ratio of total to serine-9-phosphorylated glycogen synthase kinase-3β) had the greatest power to identify mild cognitive decline in T2DM patients.<br> (10.3389/fcell.2022.818141)</p><h2 id="integrated-bioinformatics-based-identification-of-diagnostic-markers-in-alzheimer-disease" tabindex="-1"><a class="header-anchor" href="#integrated-bioinformatics-based-identification-of-diagnostic-markers-in-alzheimer-disease"><span>Integrated bioinformatics-based identification of diagnostic markers in Alzheimer disease.</span></a></h2><p>Alzheimer disease (AD) is a progressive neurodegenerative disease resulting from the accumulation of extracellular amyloid beta (Aβ) and intracellular neurofibrillary tangles.<br> There are currently no objective diagnostic measures for AD.<br> The aim of this study was to identify potential diagnostic markers for AD and evaluate the role of immune cell infiltration in disease pathogenesis.<br> AD expression profiling data for human hippocampus tissue (GSE48350 and GSE5281) were downloaded from the Gene Expression Omnibus database.<br> Differentially expressed genes (DEGs) were identified using R software and the Human Protein Atlas database was used to screen AD-related DEGs.<br> We performed functional enrichment analysis and established a protein-protein interaction (PPI) network to identify disease-related hub DEGs.<br> The fraction of infiltrating immune cells in samples was determined with the Microenvironment Cell Populations-counter method.<br> The random forest algorithm was used to develop a prediction model and receiver operating characteristic (ROC) curve analysis was performed to validate the diagnostic utility of the candidate AD markers.<br> The correlation between expression of the diagnostic markers and immune cell infiltration was also analyzed.<br> A total of 107 AD-related DEGs were screened in this study, including 28 that were upregulated and 79 that were downregulated.<br> The DEGs were enriched in the Gene Ontology terms GABAergic synapse, Morphine addiction, Nicotine addiction, Phagosome, and Synaptic vesicle cycle.<br> We identified 10 disease-related hub genes and 20 candidate diagnostic genes.<br> Synaptophysin (SYP) and regulator of G protein signaling 4 (RGS4) (area under the ROC curve = 0.909) were verified as potential diagnostic markers for AD in the GSE28146 validation dataset.<br> Natural killer cells, B lineage cells, monocytic lineage cells, endothelial cells, and fibroblasts were found to be involved in AD;<br> additionally, the expression levels of both SYP and RGS4 were negatively correlated with the infiltration of these immune cell types.<br> These results suggest that SYP and RGS4 are potential diagnostic markers for AD and that immune cell infiltration plays an important role in AD development and progression.<br> (10.3389/fnagi.2022.988143)</p>',68)]))}const c=i(r,[["render",s]]),h=JSON.parse(`{"path":"/fi/litteraturforskning/vanheneminendementia/litteratur-referenser-alzheimers-sjukdom-maskininlarning.html","title":"Alzheimers Disease and Machine Learning","lang":"fi-FI","frontmatter":{},"git":{"createdTime":1725845539000,"updatedTime":1734732075000,"contributors":[{"name":"tiikerihvgo","username":"","email":"warnghuu@yandex.com","commits":4},{"name":"afroditehvgo","username":"","email":"warnghuu@yandex.com","commits":1}]},"readingTime":{"minutes":23.28,"words":6984},"filePathRelative":"fi/litteraturforskning/vanheneminendementia/litteratur-referenser-alzheimers-sjukdom-maskininlarning.md","excerpt":"\\n<h2>Predicting mild cognitive impairment progression to Alzheimer's disease based on machine learning analysis of cortical morphological features.</h2>\\n<p>PURPOSE:<br>\\nTo establish a model for predicting mild cognitive impairment (MCI) progression to Alzheimer's disease (AD) using morphological features extracted from a joint analysis of voxel-based morphometry (VBM) and surface-based morphometry (SBM).</p>"}`);export{c as comp,h as data};
